// Diagnostic only: calls unchanged production Rust APIs. Not a benchmark gate.
use inkpod_core::{Core, PixelFormat, RenderSnapshot, RgbaRasterBytes, SequenceCellSource,
    ViewCommand, DEFAULT_DPI_MILLI};
use std::hint::black_box;
use std::time::Instant;

const BASE_UUID: u128 = 0x2026_0828_1754_1240_0000;

fn source(width: u32, height: u32, index: usize) -> SequenceCellSource {
    let mut pixels = Vec::with_capacity(width as usize * height as usize * 4);
    for y in 0..height {
        for x in 0..width {
            let ink = (x + (index as u32 * 11)) % 97 < 2 || y % 131 < 2;
            pixels.extend_from_slice(if ink { &[24, 47, 83, 255] } else { &[255, 255, 255, 255] });
        }
    }
    SequenceCellSource::from_rgba_bytes(format!("diagnostic_{index:04}.tga"), BASE_UUID + index as u128,
        RgbaRasterBytes { width, height, pixel_format: PixelFormat::StraightRgba8,
            dpi_x_milli: Some(DEFAULT_DPI_MILLI), dpi_y_milli: Some(DEFAULT_DPI_MILLI), pixels })
        .expect("valid generated source")
}

fn cache_reuse(before: &RenderSnapshot, after: &RenderSnapshot) -> usize {
    before.tiles().iter().zip(after.tiles()).filter(|(a, b)|
        a.tile_id() == b.tile_id() && a.tile_revision() == b.tile_revision()
            && a.pixels().as_ptr() == b.pixels().as_ptr()).count()
}

fn report(name: &str, mut samples: Vec<u128>) {
    let raw = samples.iter().map(ToString::to_string).collect::<Vec<_>>().join(",");
    samples.sort_unstable();
    println!("stage={name} samples_ns=[{raw}] median_ns={} min_ns={} max_ns={}",
        samples[samples.len()/2], samples[0], samples[samples.len()-1]);
}

fn main() {
    let args: Vec<_> = std::env::args().collect();
    let width: u32 = args.get(1).map(|s| s.parse().unwrap()).unwrap_or(1754);
    let height: u32 = args.get(2).map(|s| s.parse().unwrap()).unwrap_or(1240);
    let count: usize = args.get(3).map(|s| s.parse().unwrap()).unwrap_or(32);
    let measured: usize = args.get(4).map(|s| s.parse().unwrap()).unwrap_or(9);
    assert!((128..=4096).contains(&width) && (128..=4096).contains(&height));
    assert!((2..=128).contains(&count) && (3..=31).contains(&measured));
    // Two distinct, fully opaque source rasters. Catalog clones share their
    // immutable COW pixels; every catalog entry still gets a separate identity.
    let seeds = [source(width, height, 0), source(width, height, 1)];
    let cells = (0..count).map(|index| {
        let mut cell = seeds[index % 2].clone();
        cell.name = format!("diagnostic_{index:04}.tga");
        cell.cell_number = index as u32;
        cell.document_uuid = BASE_UUID + index as u128;
        cell
    }).collect();
    let mut core = Core::new();
    core.new_cell_with_uuid(1, 1, DEFAULT_DPI_MILLI, DEFAULT_DPI_MILLI, BASE_UUID - 1).unwrap();
    core.set_sequence(cells).unwrap();
    core.sequence_activate(0).unwrap();
    core.apply_view(ViewCommand::Fit { viewport_width: 1280.0, viewport_height: 800.0 }).unwrap();
    let mut previous_by_cell = [Some(core.build_snapshot()), None];
    let expected_tiles = width.div_ceil(64) as usize * height.div_ceil(64) as usize;
    let mut resolve_ns = Vec::new();
    let mut activate_ns = Vec::new();
    let mut info_ns = Vec::new();
    let mut snapshot_ns = Vec::new();
    let mut fit_math_ns = Vec::new();
    let mut repeat_snapshot_ns = Vec::new();
    let mut thumbnail_ns = Vec::new();
    let mut pane_equivalent_ns = Vec::new();
    let mut published_bytes = 0;
    let mut logical_document_bytes = 0;
    let mut fingerprint = 0_u64;
    let mut expected_checksums = [None, None];
    let mut revisit_checks = 0;
    for iteration in 0..(measured + 2) {
        let target = (iteration + 1) % 2;
        let started = Instant::now();
        let plan = core.resolve_sequence_activation(target).unwrap();
        let t_resolve = started.elapsed().as_nanos();
        let started = Instant::now();
        let activated = black_box(core.commit_sequence_activation(plan).unwrap());
        let t_activate = started.elapsed().as_nanos();
        let usage = core.resource_usage();
        assert_eq!(usage.render_cache_tile_count, 0);
        logical_document_bytes = usage.document_tile_bytes;
        let started = Instant::now();
        let info = black_box(core.document_info().unwrap());
        let t_info = started.elapsed().as_nanos();
        let started = Instant::now();
        let first = black_box(core.build_snapshot());
        let t_snapshot = started.elapsed().as_nanos();
        let started = Instant::now();
        black_box(core.apply_view(ViewCommand::Fit { viewport_width: 1280.0, viewport_height: 800.0 }).unwrap());
        let t_fit = started.elapsed().as_nanos();
        let started = Instant::now();
        let fitted = black_box(core.build_snapshot());
        let t_repeat_snapshot = started.elapsed().as_nanos();
        let started = Instant::now();
        let thumb = black_box(core.sequence_cell(target).unwrap());
        let t_thumbnail = started.elapsed().as_nanos();
        let started = Instant::now();
        for index in 0..count {
            // LoadSequence calls sequence_cell through cell_get and both
            // thumbnail_get passes. This measures the same 3N Core calls,
            // excluding Windows copies, allocations, layout, and painting.
            for _ in 0..3 { black_box(core.sequence_cell(index).unwrap()); }
        }
        let t_pane = started.elapsed().as_nanos();
        assert_eq!(activated.document_uuid, BASE_UUID + target as u128);
        assert_eq!(info.document_uuid, activated.document_uuid);
        if let Some(checksum) = expected_checksums[target] {
            assert_eq!((info.main_plane_checksum, info.color_plane_checksum), checksum);
        } else {
            expected_checksums[target] = Some((info.main_plane_checksum, info.color_plane_checksum));
        }
        assert!(!info.dirty && !core.editor_state().unwrap().dirty);
        assert!(core.history_entries().is_empty() && core.journal_entries().is_empty());
        assert_eq!(first.tile_count(), expected_tiles);
        assert_eq!(fitted.tile_count(), expected_tiles);
        if let Some(previous) = &previous_by_cell[target] {
            assert_eq!(cache_reuse(previous, &first), 0);
            revisit_checks += 1;
        }
        assert_eq!(cache_reuse(&first, &fitted), expected_tiles);
        let corner = first.tiles().iter().find(|tile| tile.origin_x() == 0 && tile.origin_y() == 0).unwrap();
        let offset = 2 * corner.stride_bytes() as usize;
        let expected_pixel = if target == 0 { [83, 47, 24, 255] } else { [255, 255, 255, 255] };
        assert_eq!(&corner.pixels()[offset..offset + 4], &expected_pixel);
        published_bytes = first.tiles().iter().map(|tile| tile.pixels().len()).sum::<usize>();
        assert_eq!(published_bytes, width as usize * height as usize * 4);
        fingerprint = fingerprint.rotate_left(7) ^ thumb.thumbnail.checksum;
        if iteration >= 2 {
            resolve_ns.push(t_resolve); activate_ns.push(t_activate); info_ns.push(t_info);
            snapshot_ns.push(t_snapshot); fit_math_ns.push(t_fit); repeat_snapshot_ns.push(t_repeat_snapshot);
            thumbnail_ns.push(t_thumbnail); pane_equivalent_ns.push(t_pane);
        }
        previous_by_cell[target] = Some(fitted);
    }
    assert_ne!(expected_checksums[0], expected_checksums[1]);
    println!("diagnostic_only=true width={width} height={height} catalog={count} measured={measured} warmup=2 unique_synthetic_sources=2 disk_reads_in_timed_phases=0 decode_in_timed_phases=0 tiles={expected_tiles} published_bytes={published_bytes} logical_document_bytes={logical_document_bytes} revisit_checks={revisit_checks} revisit_reuse=0 same_cell_reuse={expected_tiles} history=0 dirty=false fingerprint={fingerprint:016x}");
    report("resolve", resolve_ns); report("activate_including_one_info", activate_ns);
    report("document_info", info_ns); report("first_snapshot", snapshot_ns);
    report("fit_math_only", fit_math_ns); report("same_cell_snapshot", repeat_snapshot_ns);
    report("one_sequence_cell_thumbnail", thumbnail_ns); report("pane_3N_core_calls", pane_equivalent_ns);
}

